public static TelemetryStreamMessage from(BroadcastItem item) {
    Objects.requireNonNull(item, "item must not be null");
    List<SampleView> views = item.samples().stream()
        .map(sample -> new SampleView(sample.metric(), sample.value(), sample.tDevice(), sample.validationStatus()))
        .toList();
    return new TelemetryStreamMessage(item.kind().name(), item.deviceId(), views);
}
